import threadingfrom typing import List, Tuple, Set, Optional, TypedDict, NotRequired, Callablefrom pynput import keyboardimport copyimport queueimport mouseclass HotkeyType(TypedDict):    name: str    value: Set[str]    down_fun: NotRequired[Optional[Callable]]    up_fun: NotRequired[Optional[Callable]]class Keyboard:    def __init__(            self,            hotkey_list: List[HotkeyType],            tk_win=None,            save_fun: Callable[[str | None, set | None], None] | None = None,            validate_keys_fun: Callable[[str, set], None] | None = None,            is_print_info: bool = True,            is_read_mouse: bool = False,            is_read_mouse_left: bool = False,            is_read_mouse_right: bool = True,            is_read_mouse_scroll: bool = False,    ):        """        全局热键管理器。        Args:            hotkey_list: list[dict] - 热键配置列表，value请注意一定是set类型。每项格式：                {'name': str, 'value': set[str], 'down_fun': callable, 'up_fun': callable}            tk_win: tkinter.Tk or None - 若提供，回调通过 win.after 调度到主线程。如果你使用其他UI框架，请在下面的参数中使用非阻塞式的调用            save_fun: callable or None - 注册保存热键时模块会调用的函数 save_fun(name, value)。存储时请自行转换为List。            validate_keys_fun: callable or None - 注册采集模式下松手后先调用的函数 validate_keys_fun(name, value)，用于给用户展示即将设置的按键。                                            如果你注册了fitter_fun，请在用户点击“保存设置”后，调用一次set_one_hotkey_dict触发保存，该函数内部会自动触发save_fun。                                            如果你没注册，将在松手后立刻设置按键并调用save_fun。            is_print_info: 是否打印Info消息            is_read_mouse: 是否读取鼠标消息(默认False)            is_read_mouse_left: 开启鼠标后，是否读取鼠标左键(默认False)            is_read_mouse_right: 开启鼠标后，是否读取鼠标右键(默认True)            is_read_mouse_scroll: 开启鼠标后，是否读取鼠标滚轮(默认False)        """        self.validate_keys_fun=validate_keys_fun        self.save_fun=save_fun        self.is_print_info = is_print_info        self.is_read_mouse = is_read_mouse        self.is_read_mouse_left = is_read_mouse_left        self.is_read_mouse_right = is_read_mouse_right        self.is_read_mouse_scroll = is_read_mouse_scroll        def _win_after(fun,*args, **kwargs):            run_fun=lambda :fun(*args, **kwargs)            if tk_win is not None:                tk_win.after(0, run_fun)            else:                run_fun()        self.running = _win_after        self.queue = queue.Queue()        self.mouse_queue = queue.Queue()        self.hm = None        self.hotkey_setting: str | None = None        self._validate_hotkey_list(hotkey_list)        self.hotkey_list: List[HotkeyType] = hotkey_list        self.start()    def start(self):        """开启监听线程"""        self.listener_process = threading.Thread(target=self._keyboard_listener, daemon=True)        self.listener_process.start()        self.key_loop_process = threading.Thread(target=self._key_loop, daemon=True)        self.key_loop_process.start()        if self.is_read_mouse:            self.mouse_loop_process = threading.Thread(target=self._mouse_loop, daemon=True)            self.mouse_loop_process.start()            mouse.hook(lambda event: self.mouse_listener(event))    def get_hotkey_names(self) -> Tuple[str, ...]:        """        获取已注册的热键名字        """        return tuple(key_info['name'] for key_info in self.hotkey_list)    def get_hotkey_setting(self) -> str | None:        """        获取当前的按键设置状态        """        return self.hotkey_setting    def set_hotkey_setting(self, name: str | None) -> None:        """        切换到设置热键状态，软件包将读取用户接下来的热键，用户松开第一个键后，        注册了fitter_fun：            1.软件包自动调用fitter_fun。            2.请在用户点击“保存按键”后，            手动调用set_one_hotkey_dict进行按键设置应用。        没注册fitter_fun：            软件包会直接调用set_one_hotkey_dict进行按键设置应用。        set_one_hotkey_dict会自行调用你注册的save_fun函数。        Args:            name: 即将要设置的按键，None表示退出设置状态。        """        if name is not None and name not in self.get_hotkey_names():            self._xiaoe_keyboard_print(                f"未注册 {name} 按键！"                f"当前注册的按键：{self.get_hotkey_names()}",                "Warning"            )            return        if name is None:            self._xiaoe_keyboard_print(                f"已退出{self.hotkey_setting}按键设置状态"            )        else:            self._xiaoe_keyboard_print(                f"正在设置{name}按键，即将读取你按下的组合键"            )        self.hotkey_setting = name    def set_one_hotkey_dict(self, name: str, value: set) -> None:        """        用于手动触发按键的应用、保存。        Args:            name: 即将要设置的按键。            value: 按键值。        """        for i in range(len(self.hotkey_list)):            if name == self.hotkey_list[i]['name']:                self.hotkey_list[i]['value'] = value                if self.save_fun is not None:                    self.running(self.save_fun,name,value)                self._xiaoe_keyboard_print(                    f"设置{name}按键为{value}成功"                )                return        if self.save_fun is not None:            self.running(self.save_fun,None,None)            self._xiaoe_keyboard_print(                f"未注册 {name} 按键！设置失败。"                f"当前注册的按键：{self.get_hotkey_names()}",                "Warning"            )    def stop(self):        """停止监听并清理资源"""        # 1. 向队列塞入 None，解除 _key_loop 线程的阻塞        self.queue.put(None)        # 2. 停止 pynput 的底层钩子        if self.hm is not None:            self.hm.stop()        if self.is_read_mouse:            mouse.unhook_all()            self.mouse_queue.put(None)    def _keyboard_listener(self):        # 设置PyHook键盘监听        self.key_set = set()        self.hm = keyboard.Listener(on_press=self._down_keyboard, on_release=self._up_keyboard)        # 开始消息循环        self.hm.start()    def _xiaoe_keyboard_print(self, text, level = "Info"):        if not self.is_print_info and level == "Info":            return        print(f"[Xiaoe Keyboard] [{level}]: {text}")    def _validate_hotkey_list(self, hotkey_list):        """        检查 hotkey_list 格式是否符合要求。        Args:            hotkey_list: 按键列表        Raises:            TypeError: 参数不是列表，或列表元素不是字典，或类型错误            KeyError: 缺少必填字段 'name' 或 'value'            ValueError: 字段值类型不正确        """        if not isinstance(hotkey_list, list):            raise TypeError("hotkey_list 必须是列表类型")        for idx, item in enumerate(hotkey_list):            if not isinstance(item, dict):                raise TypeError(f"第 {idx} 项不是字典类型")            # 检查必填字段            if 'name' not in item:                raise KeyError(f"第 {idx} 项缺少 'name' 字段")            if 'value' not in item:                raise KeyError(f"{item['name']} 项缺少 'value' 字段")            if not isinstance(item['value'], set):                raise TypeError(f"{item['name']} 项的 'value' 必须是集合(set)类型")            # 检查可选回调            has_down = 'down_fun' in item            has_up = 'up_fun' in item            if not has_down and not has_up:                self._xiaoe_keyboard_print(                    f"{item['name']} 项 既没有 down_fun 也没有 up_fun",                    "Warning"                )            # 如果存在回调但不是可调用对象，打印警告            if has_down and not callable(item['down_fun']):                raise TypeError(                    f"{item['name']} 项的 down_fun 不可调用",                )            if has_up and not callable(item['up_fun']):                self._xiaoe_keyboard_print(                    f"{item['name']} 项的 up_fun 不可调用",                    "Warning"                )    @staticmethod    def _get_key_value(event):        try:            key=event.name        except:            try:                key=chr(event.vk)            except:                # show_suc()                return None        return key    def _down_keyboard(self, event):        #print(vars(event))        key = self._get_key_value(event)        if key is None:            return        if (key in self.key_set) or (key=="cmd"):#防止系统自动重复点击            return        self.key_set.add(key)        self.queue.put({'down': True, 'value': copy.copy(self.key_set),'now_key':key})    def _up_keyboard(self, event):        key = self._get_key_value(event)        if key is None:            return        self.queue.put({'down': False, 'value': copy.copy(self.key_set),'now_key':key})        self.key_set.discard(key)    def _key_loop(self):        """循环获取队列"""        def run_fun(m,fun_name: str):            funs=[]            value = m['value']            now_key = m['now_key']            l=0            for i in self.hotkey_list:                if i['value'] <= value:                    if now_key in i['value']:                        new_l=len(i['value'])                        if new_l>=l:                            if new_l>l:                                l=new_l                                funs=[]                            funs.append(i.get(fun_name,lambda :self._xiaoe_keyboard_print('no function')))            # if fun is not None:            for fun in funs:                self.running(fun)        while True:            m = self.queue.get(block=True)            if m is None:                break            # print(m)            if m['down']:                run_fun(m,'down_fun')                #self.restart.next()            else:                if not self.hotkey_setting is None:                    if self.validate_keys_fun is not None:                        self.running(self.validate_keys_fun, self.hotkey_setting, m['value'])                    else:                        self.set_one_hotkey_dict(self.hotkey_setting,m['value'])                    self.set_hotkey_setting(None)                else:                    run_fun(m,'up_fun')                    #self.restart.next()    def _mouse_loop(self):        while True:            event = self.mouse_queue.get(block=True)            if event is None:                break            if isinstance(event, mouse.ButtonEvent):                button = f'mouse_{event.button}'                if not self.is_read_mouse_left and button == 'mouse_left':                    continue                if not self.is_read_mouse_right and button == 'mouse_right':                    continue                event_type = event.event_type                is_down = event_type != 'up'                if is_down:                    self.key_set.add(button)                self.queue.put({'down': is_down, 'value': copy.copy(self.key_set), 'now_key': button})                if not is_down:                    self.key_set.discard(button)                continue            if isinstance(event, mouse.WheelEvent) and self.is_read_mouse_scroll:                button = f'mouse_scroll_{'up' if event.delta > 0 else 'down'}'                self.key_set.add(button)                self.queue.put({'down': True, 'value': copy.copy(self.key_set), 'now_key': button})                self.queue.put({'down': False, 'value': copy.copy(self.key_set), 'now_key': button})                self.key_set.discard(button)                continue    def mouse_listener(self, event):        if isinstance(event, (mouse.ButtonEvent, mouse.WheelEvent)):            self.mouse_queue.put(event)if __name__ == "__main__":    '''示例用法'''    """====    完整使用示例    =================================="""    def full_use():        import tkinter as tk        win = tk.Tk()        DEFAULT_KEYS1 = ['D']        DEFAULT_KEYS2 = ['ctrl_l', 'D']        DEFAULT_KEYS3 = ['ctrl_l','shift','D']        def down_fun(n=None):  # 按下热键执行的方法            if n is None:                n='第三个'            print(n,'你按下了热键！')        def up_fun(n=None):  # 松开热键执行的方法            if n is None:                n='第三个'            print(n,'你松开了热键！')        hotkey_list: List[HotkeyType] = [            {'name': '热键示例0', 'value': set(DEFAULT_KEYS1), 'down_fun': lambda :down_fun(0), 'up_fun': lambda :up_fun(0), },            {'name': '热键示例1', 'value': set(DEFAULT_KEYS2), 'down_fun': lambda :down_fun(1)},            {'name': '热键示例2', 'value': set(DEFAULT_KEYS3),                                  'up_fun': up_fun}        ]  # 存储热键的字典列表                                                   (可以不用写lambda)        #             热键名字(必选)         热键值（集合，必选）         按下触发函数（可选）              松开触发函数（可选）        def save_fun(name,value):            """保存热键配置"""            btn_index=int(name[-1])            btn_list[btn_index].config(text='设置热键')            print("\n保存热键配置成功：",name,value)            #在这里保存热键配置到文件或数据库等        will_save_hotkey = dict()#热键暂存，支持批量设置批量保存        def validate_keys_fun(name,value):            """预处理热键"""            will_save_hotkey[name] = value            print(f"\n\n请点击保存按钮保存热键：new    name:{name}  value:{value}")            for key,value in will_save_hotkey.items():                print(f"即将保存的热键：name:{key}  value:{value}")            print("\n")            #在这里对热键值进行暂存（若不填validate_keys_fun，则直接保存）        keyboard = Keyboard(            hotkey_list,  # 热键配置信息            tk_win=win, # 窗口对象            save_fun=save_fun, # 保存成功回调函数            validate_keys_fun=validate_keys_fun, # 预处理回调函数（松手触发。置空则松手直接保存）,            is_read_mouse=True, # 开启鼠标识别            is_read_mouse_right=True, # 开启鼠标右键识别            is_read_mouse_scroll=True, # 开启鼠标滚轮识别        )        def button_fun(n):            """触发修改"""            print(will_save_hotkey)            if keyboard.get_hotkey_setting() is None:                print(f'正在设置：热键示例{n}...')                btn_list[n].config(text='取消设置')                keyboard.set_hotkey_setting(f'热键示例{n}')#发送信号，开启识别热键功能（目标热键名字，只能同时设置一个）            else:                print('取消设置')                btn_list[n].config(text=f'设置热键{n}')                keyboard.set_hotkey_setting(None)#再次按下按钮，发送信号，关闭识别热键功能        set_button0 = tk.Button(win, text='设置热键0', command=lambda :button_fun(0))        set_button0.pack(pady=15)        set_button1 = tk.Button(win, text='设置热键1', command=lambda :button_fun(1))        set_button1.pack(pady=15)        set_button2 = tk.Button(win, text='设置热键2', command=lambda :button_fun(2))        set_button2.pack(pady=15)        btn_list=[set_button0,set_button1,set_button2]        def call_save():            """通知保存"""            if will_save_hotkey:                for name,value in will_save_hotkey.items():#批量保存                    keyboard.set_one_hotkey_dict(name,value)                will_save_hotkey.clear()        save_button = tk.Button(win, text='保存热键', command=call_save)        save_button.pack(pady=30)        win.geometry(f'300x300+{win.winfo_screenwidth()//2-150}+{win.winfo_screenheight()//2-150}')        try:            win.mainloop()        finally:            print('exit')    """====    最小使用示例    =================================="""    def simple():        def fun99():            print('你按下了热键99！')        hotkey=['ctrl_l', 'R']        hotkey_list: List[HotkeyType] = [            {'name': '热键示例99', 'value': set(hotkey),'down_fun': fun99},        ]        Keyboard(hotkey_list)        while True:            if input('输入quit退出...')=='quit':                break    """====    运行示例    ===="""    run = 0    #0：完整使用示例   1：最小使用示例(固定热键：ctrl_l + R)    if run==0:        full_use()    elif run==1:        simple()